SELECT p.id AS position_id, e.id AS entry_1m_id, e.generated_at AS e_gen, e.created_at AS e_created, s.id AS s5_id, s.candle_open_time, s.generated_at, s.created_at, TIMESTAMPDIFF(MICROSECOND, s.created_at, e.generated_at)/1000 AS visible_before_1m_gen_ms, s.decision, s.original_decision, s.total_score, s.confidence_score, s.atr_at_signal, s.atr_entry_type, s.atr_immediate_entry_allowed FROM paper_position p JOIN trade_signal e ON e.id=p.signal_id JOIN trade_signal s ON s.symbol=p.symbol AND s.interval_code='5m' AND s.generated_at BETWEEN e.generated_at - INTERVAL 6 MINUTE AND e.generated_at + INTERVAL 10 SECOND WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, s.generated_at LIMIT 60